I have a small conversion utility that transforms interaction logs from one chat framework into the training format expected by another. The converter lives at `tools/convert_session.py`, and there are unit tests in `tools/test_convert_session.py`.

The code already supports basic user/assistant turns and can optionally attach internal reasoning sections. However, it does not currently reconstruct tool invocations as structured assistant tool calls. Please improve it so that when a session contains a `tool_invocation` event, the converted output includes:

- An assistant message with a `tool_calls` list, where each item has:
  - `id`
  - `type: "function"`
  - `function.name`
  - `function.arguments` as a JSON string
- A subsequent `tool` role message containing the tool result.
- The original assistant response after the tool result.

Please update the implementation and tests accordingly. Also, explain how someone can run the system without using SkyPilot, either by using a local execution path or by submitting jobs directly with the underlying learner/syncer interfaces.

Here are the current files:

```python
# tools/convert_session.py
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional


@dataclass
class Segment:
    role: str
    content: str
    weight: float = 1.0
    extra: Optional[Dict[str, Any]] = None


def _normalize_content(content: Any) -> str:
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    return json.dumps(content, ensure_ascii=False, sort_keys=True)


def _append_message(
    segments: List[Segment],
    role: str,
    content: Any,
    *,
    weight: float = 1.0,
    extra: Optional[Dict[str, Any]] = None,
) -> None:
    normalized = _normalize_content(content)
    if not normalized and not extra:
        return
    segments.append(
        Segment(
            role=role,
            content=normalized,
            weight=weight,
            extra=extra,
        )
    )


def _reasoning_text(event: Dict[str, Any]) -> str:
    reasoning = event.get("reasoning")
    if reasoning is None:
        return ""
    if isinstance(reasoning, list):
        return "\n".join(_normalize_content(item) for item in reasoning)
    return _normalize_content(reasoning)


def _tool_call_payload(event: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "id": event.get("call_id") or event.get("id") or "",
        "type": "function",
        "function": {
            "name": event.get("name") or event.get("tool_name") or "",
            "arguments": json.dumps(
                event.get("arguments") or event.get("input") or {},
                ensure_ascii=False,
                sort_keys=True,
            ),
        },
    }


def convert_events(
    events: Iterable[Dict[str, Any]],
    *,
    include_reasoning: bool = False,
) -> List[Segment]:
    """
    Convert session events into training segments.

    The input stream is an event sequence such as:
      {"type": "user", "content": "..."}
      {"type": "assistant", "content": "...", "reasoning": "..."}
      {"type": "tool_invocation", "name": "...", "arguments": {...}}
      {"type": "tool_result", "content": "..."}
    """
    segments: List[Segment] = []

    for event in events:
        event_type = event.get("type")

        if event_type == "user":
            _append_message(segments, "user", event.get("content"), weight=0.0)

        elif event_type == "assistant":
            reasoning = _reasoning_text(event) if include_reasoning else ""
            content = event.get("content")
            if reasoning:
                content = f"<think>\n{reasoning}\n</think>\n{_normalize_content(content)}"
            _append_message(segments, "assistant", content, weight=1.0)

        elif event_type == "tool_invocation":
            # TODO: preserve tool calls as structured assistant messages.
            _append_message(
                segments,
                "assistant",
                f"Calling tool {event.get('name') or event.get('tool_name')}",
                weight=1.0,
            )

        elif event_type == "tool_result":
            _append_message(
                segments,
                "tool",
                event.get("content") or event.get("result"),
                weight=0.0,
            )

    return segments


def _fallback_segments(segments: List[Segment]) -> List[Dict[str, Any]]:
    """
    Convert internal segments into a simple chat-training representation.

    Some consumers only understand role/content messages. For those consumers,
    tool call metadata is rendered as a JSON block in the assistant content.
    """
    output: List[Dict[str, Any]] = []

    for segment in segments:
        message: Dict[str, Any] = {
            "role": segment.role,
            "content": segment.content,
        }
        if segment.extra:
            message.update(segment.extra)
        if segment.weight != 1.0:
            message["weight"] = segment.weight
        output.append(message)

    return output


def convert_file(
    source: Path,
    destination: Path,
    *,
    include_reasoning: bool = False,
) -> None:
    with source.open("r", encoding="utf-8") as handle:
        events = json.load(handle)

    segments = convert_events(events, include_reasoning=include_reasoning)
    payload = _fallback_segments(segments)

    with destination.open("w", encoding="utf-8") as handle:
        json.dump(payload, handle, ensure_ascii=False, indent=2)
        handle.write("\n")
```

```python
# tools/test_convert_session.py
import json

from convert_session import convert_events, convert_file


def test_converts_basic_messages():
    events = [
        {"type": "user", "content": "Hello"},
        {"type": "assistant", "content": "Hi there"},
    ]

    result = convert_events(events)

    assert [(item.role, item.content) for item in result] == [
        ("user", "Hello"),
        ("assistant", "Hi there"),
    ]
    assert [item.weight for item in result] == [0.0, 1.0]


def test_includes_reasoning_when_requested():
    events = [
        {
            "type": "assistant",
            "reasoning": ["first thought", "second thought"],
            "content": "Final answer",
        }
    ]

    result = convert_events(events, include_reasoning=True)

    assert result[0].content == (
        "<think>\nfirst thought\nsecond thought\n</think>\nFinal answer"
    )


def test_tool_invocation_and_result_are_preserved():
    events = [
        {"type": "user", "content": "What is the weather?"},
        {
            "type": "tool_invocation",
            "call_id": "call-1",
            "name": "get_weather",
            "arguments": {"city": "Paris"},
        },
        {
            "type": "tool_result",
            "content": '{"temperature": 18, "unit": "C"}',
        },
        {"type": "assistant", "content": "It is 18°C in Paris."},
    ]

    result = convert_events(events)

    assert [(item.role, item.content) for item in result] == [
        ("user", "What is the weather?"),
        ("assistant", "Calling tool get_weather"),
        ("tool", '{"temperature": 18, "unit": "C"}'),
        ("assistant", "It is 18°C in Paris."),
    ]

    fallback = [
        {
            "role": item.role,
            "content": item.content,
            **(item.extra or {}),
        }
        for item in result
    ]

    assert fallback[1]["extra"] == {
        "id": "call-1",
        "type": "function",
        "function": {
            "name": "get_weather",
            "arguments": '{"city": "Paris"}',
        },
    }


def test_convert_file(tmp_path):
    source = tmp_path / "events.json"
    destination = tmp_path / "converted.json"

    source.write_text(
        json.dumps(
            [
                {"type": "user", "content": "Ping"},
                {"type": "assistant", "content": "Pong"},
            ]
        ),
        encoding="utf-8",
    )

    convert_file(source, destination)

    assert json.loads(destination.read_text(encoding="utf-8")) == [
        {"role": "user", "content": "Ping", "weight": 0.0},
        {"role": "assistant", "content": "Pong"},
    ]
```

Current behavior for the tool test is wrong because it emits a plain assistant string like `"Calling tool get_weather"` and does not include a subsequent assistant tool-call payload. Please make the smallest clean change that fixes this while preserving existing behavior.

